findings.codeql_raw_query:
/**
 * @name Server-Side Request Forgery (SSRF)
 * @description HTTP requests with user-controlled URLs can lead to SSRF attacks
 * @kind path-problem
 * @problem.severity high
 * @id py/ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // requests library
      call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "head", "options", "request"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // urllib/urllib2
      call = API::moduleImport("urllib").getMember(["request", "urlopen"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // httplib/http.client
      call = API::moduleImport("http").getMember("client").getMember(["HTTPConnection", "HTTPSConnection"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SsrfFlow = TaintTracking::Global<SsrfConfig>;
import SsrfFlow::PathGraph

from SsrfFlow::PathNode source, SsrfFlow::PathNode sink
where SsrfFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability: user-controlled URL in HTTP request from $@.", source.getNode(), "user input"
